  const [text, finishReason, usage] = await Promise.all([
    result.text,
    result.finishReason,
    result.usage,
  ]);

  return {
    text,
    finishReason,
    inputTokens: usage.inputTokens,
    outputTokens: usage.outputTokens,
  };
}

